@pytest.mark.parametrize("case", sorted(CASES))
def test_parse_corpus(run, workdir, case):
    """CATCHES: a pretty-printer that parenthesises, indents or spells constructs differently from the
    reference canonical form, a parser that accepts syntax the reference rejects (or the reverse), or a
    syntax error reported with a different message, location or caret."""
    mode, source = CASES[case]
    (workdir / "prog.pyfun").write_text(source, encoding="utf-8")
    r = run(ARGS[mode])
    expected = json.loads(golden(__file__, f"{case}.json"))
    assert r.stdout.decode() == expected["stdout"]
    assert r.stderr.decode() == expected["stderr"]
    assert r.returncode == expected["exit"]
